```csharp
// Components/Pages/Catalog.razor
@page "/catalog"
@using sv_7c53eb5090644cb7aee51f97e30628ad.Components.Catalog

<div class="catalog-container">
    <CatalogSidebar OnFiltersChanged="HandleFiltersChanged" />
    <div class="catalog-main">
        <CatalogToolbar OnSearch="HandleSearch" OnSortChange="HandleSort" />
        <ProductGrid Products="FilteredProducts" OnAddToCart="HandleAddToCart" />
        <CatalogPagination CurrentPage="CurrentPage" TotalPages="TotalPages" OnPageChange="HandlePageChange" />
    </div>
</div>

@code {
    private List<Product> AllProducts = new();
    private List<Product> FilteredProducts = new();
    private int CurrentPage = 1;
    private int TotalPages = 1;
    private const int ItemsPerPage = 12;

    protected override async Task OnInitializedAsync()
    {
        AllProducts = await LoadProducts();
        ApplyFilters();
    }

    private async Task<List<Product>> LoadProducts()
    {
        // Load from API or database
        return new List<Product>();
    }

    private void HandleFiltersChanged(FilterOptions filters)
    {
        CurrentPage = 1;
        ApplyFilters();
    }

    private void HandleSearch(string query)
    {
        CurrentPage = 1;
        ApplyFilters();
    }

    private void HandleSort(string sortOption)
    {
        ApplyFilters();
    }

    private void HandlePageChange(int page)
    {
        CurrentPage = page;
        ApplyFilters();
    }

    private void HandleAddToCart(Product product)
    {
        // Add to cart logic
    }

    private void ApplyFilters()
    {
        // Apply all filters and pagination
        TotalPages = (int)Math.Ceiling(FilteredProducts.Count / (double)ItemsPerPage);
    }
}
```

