{"path": "/tmp/sv-7c53eb5090644cb7aee51f97e30628ad/Components/Catalog/CatalogSidebar.razor", "file_text": "<div class="p-3 border rounded bg-white">
    <h5>Filters</h5>

    <div class="mb-3">
        <h6>Categories</h6>
        @foreach (var category in Categories)
        {
            <div class="form-check">
                <input class="form-check-input" type="checkbox"
                       id="@($"cat-{category}")"
                       checked="@selectedCategories.Contains(category)"
                       @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                <label class="form-check-label" for="@($"cat-{category}")">@category</label>
            </div>
        }
    </div>

    <div class="mb-3">
        <h6>Price Range</h6>
        <div class="mb-2">
            <label class="form-label mb-0 small">Min Price</label>
            <input type="number" class="form-control form-control-sm"
                   @bind="minPrice" min="0" step="0.01" placeholder="0" />
        </div>
        <div class="mb-2">
            <label class="form-label mb-0 small">Max Price</label>
            <input type="number" class="form-control form-control-sm"
                   @bind="maxPrice" min="0" step="0.01" placeholder="Any" />
        </div>
    </div>

    <div class="mb-3">
        <div class="form-check">
            <input class="form-check-input" type="checkbox"
                   id="inStockOnly"
                   @bind="inStockOnly" />
            <label class="form-check-label" for="inStockOnly">In Stock Only</label>
        </div>
    </div>

    <div class="d-grid gap-2">
        <button class="btn btn-primary btn-sm" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnApplyFilters { get; set; }

    [Parameter]
    public EventCallback OnClearFilters { get; set; }

    private HashSet<string> selectedCategories = [];
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
        await OnApplyFilters.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        await OnClearFilters.InvokeAsync();
    }
}
"}

{"path": "/tmp/sv-7c53eb5090644cb7aee51f97e30628ad/Components/Catalog/CatalogToolbar.razor", "file_text": "<div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
