    private static readonly (string Value, string Label)[] sortOptions =
    [
        ("price-asc", "Price: Low to High"),
        ("price-desc", "Price: High to Low"),
        ("name-asc", "Name: A-Z"),
        ("rating-desc", "Rating: Highest")
    ];

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString());
    }
}
"}

