@page "/catalog"
@using sv_7c53eb5090644cb7aee51f97e30628ad.Components.Catalog
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-3">Product Catalog</h3>

<div class="d-flex gap-3">
    <aside style="min-width: 240px; flex: 0 0 25%;">
        <CatalogSidebar Categories="categories"
                        OnApplyFilters="HandleApplyFilters"
                        OnClearFilters="HandleClearFilters" />
    </aside>

    <main style="flex: 1 1 75%;">
        @if (isLoading)
        {
            <div class="text-center py-5">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
                <p class="mt-2 text-muted">Loading products…</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
                <button class="btn btn-link p-0 ms-2" @onclick="LoadProducts">Try again</button>
            </div>
        }
        else if (result is { Items.Count: 0 })
        {
            <div class="text-center py-5">
                <p class="text-muted fs-5">No products found matching your criteria.</p>
            </div>
        }
        else if (result is not null)
        {
            <CatalogToolbar CurrentSort="@currentSort"
                            TotalCount="@result.TotalCount"
                            CurrentPage="@result.Page"
                            PageSize="@result.PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="@result.Items"
                         OnProductSelected="OnProductSelected"
                         OnAddToCart="HandleAddToCart" />

            @{
                var totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
            }
            @if (totalPages > 1)
            {
                <CatalogPagination CurrentPage="@result.Page"
                                   TotalPages="@totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </main>
</div>

@code {
    private List<string> categories = [];
    private PagedResult<Product>? result;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string currentSort = "name-asc";
    private int currentPage = 1;
    private const int PageSize = 12;
    private bool isLoading = true;
    private string? errorMessage;

    /// <summary>
    /// Raised when a product card is clicked so the parent can navigate to a detail page.
    /// </summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            categories = await ProductService.GetCategoriesAsync();
            result = await ProductService.SearchAsync(currentFilter, currentSort, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            result = await ProductService.SearchAsync(currentFilter, currentSort, currentPage, PageSize);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleClearFilters()
    {
        currentFilter = new(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string? sortBy)
    {
        currentSort = sortBy ?? "name-asc";
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        return Task.CompletedTask;
    }
}

